module EmailGateway
  # Provider-agnostic e-mail (immutable value object). Adapters translate it into their wire format.
  class Message < Data.define(:to, :from, :subject, :html, :text, :headers, :idempotency_key)
    # Only these headers are forwarded to the provider (the rest are generated by Mail).
    FORWARDED_HEADERS = /\A(List-|X-|Reply-To\z)/i

    def initialize(to:, from:, subject:, html: nil, text: nil, headers: {}, idempotency_key: nil)
      super(to: Array(to), from:, subject:, html:, text:, headers:, idempotency_key:)
    end

    # Builds a Message from the Mail::Message produced by an ActionMailer mailer, so
    # templates/layouts keep living in app/views while delivery goes through the gateway.
    def self.from_mail(mail, idempotency_key: nil)
      new(
        to: mail.to,
        from: mail[:from].to_s,
        subject: mail.subject,
        html: part_body(mail, "text/html"),
        text: part_body(mail, "text/plain"),
        headers: mail.header.fields.select { it.name.match?(FORWARDED_HEADERS) }.to_h { [it.name, it.value.to_s] },
        idempotency_key:
      )
    end

    def self.part_body(mail, mime_type)
      part = mail.multipart? ? mail.all_parts.find { it.mime_type == mime_type } : (mail if mail.mime_type == mime_type)
      part&.decoded
    end
    private_class_method :part_body
  end
end
